import{_ as a,o as e,c as n,ae as i}from"./chunks/framework.BX6FPmO9.js";const c=JSON.parse('{"title":"Design Pattern UI Kit 選型與技術評估","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/design-pattern-ui-kit.md","filePath":"architecture/design-pattern-ui-kit.md"}'),r={name:"architecture/design-pattern-ui-kit.md"};function o(d,t,s,l,g,p){return e(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="design-pattern-ui-kit-選型與技術評估" tabindex="-1">Design Pattern UI Kit 選型與技術評估 <a class="header-anchor" href="#design-pattern-ui-kit-選型與技術評估" aria-label="Permalink to &quot;Design Pattern UI Kit 選型與技術評估&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本文件記錄 Figma 端 <strong>design system / UI kit</strong> 的選型評估：候選名單、評估維度、建議方向與導入前驗證。元件骨架以 <a href="./../DESIGN_SYSTEM.html">shadcn/ui</a> 為準、不替換；UI kit 僅作為設計層 pattern 與視覺參考，經 <a href="./figma-mcp.html">figma-mcp</a> 與 token 同步接入。</p><hr><h2 id="一、決策前提" tabindex="-1">一、決策前提 <a class="header-anchor" href="#一、決策前提" aria-label="Permalink to &quot;一、決策前提&quot;">​</a></h2><ul><li><strong>shadcn/ui</strong> 維持為 <strong>component 層</strong>：Radix + Tailwind、程式碼在 repo、可改。不替換。</li><li><strong>目標</strong>：找一個 <strong>Figma 端的 design system / UI kit</strong>，提供： <ul><li>設計 pattern（screen、layout、product 情境）</li><li>視覺方向（外觀）</li><li>可選：design token 結構，供「Figma → repo token」mapping 參考</li></ul></li><li><strong>Pipeline</strong>：Figma Design System → Design Tokens → shadcn/ui components → AI coding（已具備 <a href="./figma-mcp.html">Figma MCP</a>、<a href="./../DESIGN_SYSTEM.html">token canonical 在 repo</a>）。</li><li><strong>產品型態</strong>（<a href="./../product/overview.html">overview</a>）：AI Search Portal、LUI Chat、輕量項目/領域功能、release notes；偏 <strong>AI tool / agent interface</strong>，非傳統大型 SaaS dashboard。</li></ul><hr><h2 id="二、評估維度" tabindex="-1">二、評估維度 <a class="header-anchor" href="#二、評估維度" aria-label="Permalink to &quot;二、評估維度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>說明</th><th>與本專案關係</th></tr></thead><tbody><tr><td><strong>Token 結構</strong></td><td>color / spacing / typography / radius / shadow 是否完整、可 export 或可對照</td><td>需能對應到 <code>app/tailwind.css</code> 與 semantic token；Figma → repo mapping 依 <a href="./figma-mcp.html">figma-mcp §3</a></td></tr><tr><td><strong>Component state</strong></td><td>default / hover / focus / disabled / loading 等</td><td>與 shadcn 的 variant 對齊，減少 design→code 落差</td></tr><tr><td><strong>Product pattern</strong></td><td>table / filter / settings / onboarding / dashboard 等</td><td>覆蓋首頁、Chat、列表、設定等情境；若含 chat/copilot 更佳</td></tr><tr><td><strong>Tailwind / code 對齊</strong></td><td>是否用 Tailwind 尺度或提供 code 對應</td><td>降低 design→code translation 成本，符合現有 stack</td></tr><tr><td><strong>Figma → code 可對應性</strong></td><td>Figma component 能否 mapping 到 shadcn 或明確規格</td><td>影響 MCP / AI 產出與人工維護量</td></tr></tbody></table><hr><h2 id="三、候選對照" tabindex="-1">三、候選對照 <a class="header-anchor" href="#三、候選對照" aria-label="Permalink to &quot;三、候選對照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>候選</th><th>Token 結構</th><th>Component state</th><th>Product pattern</th><th>Tailwind/code</th><th>Figma→code</th><th>備註</th></tr></thead><tbody><tr><td><strong>Untitled UI</strong></td><td>完整（typography/color 等）</td><td>狀態完整</td><td>dashboard / auth / tables</td><td>需自行對應</td><td>需建 mapping</td><td>平衡好，SaaS/AI 常用</td></tr><tr><td><strong>Frames X</strong></td><td>有</td><td>完整</td><td>CRM / SaaS 覆蓋廣</td><td>需自行對應</td><td>需建 mapping</td><td>規模大，導入成本高</td></tr><tr><td><strong>Flowbite Design System</strong></td><td>有</td><td>中等</td><td>dashboard</td><td><strong>Tailwind 原生</strong></td><td><strong>design→Tailwind 清楚</strong></td><td>與 Tailwind 棧最貼合</td></tr><tr><td><strong>UI Prep</strong></td><td>較簡化</td><td>需確認</td><td>SaaS screens / onboarding</td><td>需確認</td><td>需建 mapping</td><td>screen pattern 多</td></tr><tr><td><strong>Design System For Figma</strong></td><td>需確認</td><td>需確認</td><td>product / dashboard / CRM</td><td>需確認</td><td>需確認</td><td>覆蓋高，一致性需驗證</td></tr></tbody></table><hr><h2 id="四、建議方向-依目標取捨" tabindex="-1">四、建議方向（依目標取捨） <a class="header-anchor" href="#四、建議方向-依目標取捨" aria-label="Permalink to &quot;四、建議方向（依目標取捨）&quot;">​</a></h2><h3 id="若優先「figma-ai-coding-pipeline」與-tailwind-棧" tabindex="-1">若優先「Figma + AI coding pipeline」與 Tailwind 棧 <a class="header-anchor" href="#若優先「figma-ai-coding-pipeline」與-tailwind-棧" aria-label="Permalink to &quot;若優先「Figma + AI coding pipeline」與 Tailwind 棧&quot;">​</a></h3><ul><li><p><strong>首選：Flowbite Design System</strong></p><ul><li>理由：design → Tailwind mapping 明確、token 與 spacing 易對齊 <a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a> 與 <code>app/tailwind.css</code>，Figma 變數與 repo token 的 transformation layer 負擔較小。</li><li>取捨：variant 深度與 pattern 廣度不如 Untitled UI / Frames X；對「AI portal + LUI」是否足夠需看實際 Figma 內容。</li></ul></li><li><p><strong>次選：Untitled UI</strong></p><ul><li>理由：token + component 品質好、SaaS/AI product 常見，pattern 完整。</li><li>取捨：Tailwind 對應與 token 命名需自己建（符合現有「repo 為 token canonical」與 <a href="./figma-mcp.html">figma-mcp</a> 的 mapping 設計）。</li></ul></li></ul><h3 id="若優先「enterprise-大量-pattern」" tabindex="-1">若優先「enterprise / 大量 pattern」 <a class="header-anchor" href="#若優先「enterprise-大量-pattern」" aria-label="Permalink to &quot;若優先「enterprise / 大量 pattern」&quot;">​</a></h3><ul><li><strong>Frames X</strong> 適合 component 與 layout 需求極多的情境；對目前 AI Search Portal 規模可能過重，可列為後續擴充選項。</li></ul><h3 id="若優先「screen-pattern-onboarding」" tabindex="-1">若優先「screen pattern / onboarding」 <a class="header-anchor" href="#若優先「screen-pattern-onboarding」" aria-label="Permalink to &quot;若優先「screen pattern / onboarding」&quot;">​</a></h3><ul><li><strong>UI Prep</strong> 可補足畫面級 pattern；需單獨確認 token 結構與 state 是否足夠做 design system governance。</li></ul><hr><h2 id="五、導入前驗證-三件事" tabindex="-1">五、導入前驗證（三件事） <a class="header-anchor" href="#五、導入前驗證-三件事" aria-label="Permalink to &quot;五、導入前驗證（三件事）&quot;">​</a></h2><p>鎖定單一 UI kit 前建議確認：</p><ol><li><p><strong>Design token 是否可 export 或對照</strong></p><ul><li>Figma Variables / 樣式是否具備 color / spacing / typography / radius（及必要時 shadow）。</li><li>能否產出或整理成一份「Figma token 清單」，以便寫 <code>specs/figma-token-mapping.md</code> 或等同的 mapping 規格。</li></ul></li><li><p><strong>Figma component 與 code component 的對應</strong></p><ul><li>關鍵畫面（例如首頁、Chat、Card、Button）在 Figma 的 component 是否具備穩定命名與 props/variants，能否在文件中定義「Figma component key / name → shadcn 元件 + variant」對照表，供 MCP / AI 與人工維護使用。</li></ul></li><li><p><strong>UI kit 是否對齊 Tailwind spacing / scale</strong></p><ul><li>若 kit 使用 4/8px 或 8px grid 等常見尺度，與 Tailwind 預設較易對齊；若有自訂 spacing，需在 token transformation 中明確定義（避免 layout authority 混亂，見 <a href="./figma-mcp.html">figma-mcp §4.3</a>）。</li></ul></li></ol><p><strong>驗證結果</strong>（選定 kit 後填寫）：</p><table tabindex="0"><thead><tr><th>項目</th><th>結果</th><th>備註</th></tr></thead><tbody><tr><td>Token export / 對照</td><td>待驗證</td><td>選定 Figma 來源後填寫</td></tr><tr><td>Component 對應</td><td>待驗證</td><td>選定 Figma 來源後填寫</td></tr><tr><td>Tailwind spacing 對齊</td><td>待驗證</td><td>選定 Figma 來源後填寫</td></tr></tbody></table><hr><h2 id="六、ai-product-ui-pattern-獨立於-ui-kit-選型" tabindex="-1">六、AI product UI pattern（獨立於 UI kit 選型） <a class="header-anchor" href="#六、ai-product-ui-pattern-獨立於-ui-kit-選型" aria-label="Permalink to &quot;六、AI product UI pattern（獨立於 UI kit 選型）&quot;">​</a></h2><p>「AI product UI patterns」（chat / workflow / agent / copilots）與傳統 SaaS dashboard 的 pattern 不同：</p><ul><li><strong>本專案已有</strong>：LUI Chat、結論/依據/下一步、<code>app/components/shared/chat/ChatInterface.tsx</code> 等，屬 AI 介面 pattern。</li><li><strong>建議</strong>： <ul><li>UI kit 選型先以 <strong>token + 通用 product pattern + Tailwind 對齊</strong> 為主。</li><li><strong>Chat / agent / copilot 專用 pattern</strong> 可列為單獨的「AI product UI patterns」研究或第二層：例如在 Figma 自建一頁「LUI / Chat patterns」或參考現成 AI UI 範本，與主 UI kit 並存，不綁死在同一套 kit。</li></ul></li><li><strong>後續</strong>：若需強化 LUI/Chat 視覺與 pattern，再單獨規劃「AI product UI patterns」來源與 Figma 結構（不影響主 UI kit 選型）。</li></ul><hr><h2 id="七、建議產出與後續" tabindex="-1">七、建議產出與後續 <a class="header-anchor" href="#七、建議產出與後續" aria-label="Permalink to &quot;七、建議產出與後續&quot;">​</a></h2><ol><li><p><strong>選型結果</strong>（選定後更新本節）</p><ul><li>目前建議：優先評估 <strong>Flowbite Design System</strong>，次選 <strong>Untitled UI</strong>。選定後在此記錄最終採用 kit 與理由。</li></ul></li><li><p><strong>Token / mapping</strong></p><ul><li>選定 Figma UI kit 後，依 <a href="./figma-mcp.html">figma-mcp</a> 完成： <ul><li>design token schema（可放 <code>specs/design-token-schema.md</code> 或本目錄）；</li><li>figma → token mapping（可放 <code>specs/figma-token-mapping.md</code>）；</li><li>可先從一小部分 token 試跑，再逐步擴充。</li></ul></li></ul></li><li><p><strong>AI pattern</strong></p><ul><li>與主 UI kit 分開規劃；可於 Figma 自建「LUI / Chat patterns」或參考 AI 介面範本，與主 kit 並存。</li></ul></li></ol><p><strong>不變原則</strong>：shadcn/ui 仍是元件骨架，repo 仍是 token 與 layout 權威；所選 Figma UI kit 僅作為設計層的 pattern 與視覺參考，經由既有 Figma MCP 與 token transformation 接入，不取代現有架構。</p><hr><h2 id="八、小結" tabindex="-1">八、小結 <a class="header-anchor" href="#八、小結" aria-label="Permalink to &quot;八、小結&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目標</th><th>建議</th></tr></thead><tbody><tr><td><strong>外觀 + design pattern，且與 Tailwind / Figma→code 貼合</strong></td><td>優先評估 <strong>Flowbite Design System</strong>，並做三項驗證。</td></tr><tr><td><strong>要更完整 token + SaaS pattern</strong></td><td>併用或改選 <strong>Untitled UI</strong>，並接受自建 token mapping。</td></tr><tr><td><strong>Figma + AI coding pipeline</strong></td><td>任一 kit 都需落實：token 可對照、component 可對應、spacing 可對齊；文件化於 design-system / figma-mcp。</td></tr><tr><td><strong>AI 專用 pattern（chat / agent）</strong></td><td>與主 UI kit 分開規劃，作為補充。</td></tr></tbody></table><hr><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./../DESIGN_SYSTEM.html">DESIGN_SYSTEM.md</a>：Token canonical、Core components</li><li><a href="./design-system.html">design-system</a>：半自動化 UI、分層結構</li><li><a href="./figma-mcp.html">figma-mcp</a>：Figma MCP、Token transformation、導入順序</li><li><a href="./../product/overview.html">overview</a>：產品型態與功能一覽</li></ul>',40)])])}const m=a(r,[["render",o]]);export{c as __pageData,m as default};
